"""Render the English report from measured receipts, without inventing results."""
from pathlib import Path
from statistics import median
import json,html
ROOT=Path(__file__).resolve().parent;LOG=ROOT/'logs/isolation-latency'
def read(name):return json.loads((LOG/name).read_text())
def result(row):return next(e for e in row['events'] if e['event']=='result')
def num(x):return f'{x:,.0f}'
def main():
 before=read('parallel-first-pass.json');after=read('parallel-optimized.json');early=read('parallel-early-scan.json')
 browser_name='browser-deployed-final-voxlock.json'
 browser=read(browser_name);cancel=read('parallel-cancellation.json')
 deployed=read('parallel-deployed.json');long_run=read('parallel-long-fixed.json')
 rows=[]
 for label,data,mode in [('Previous serial',before,'serial'),('Serial + reset graph (same process)',after,'serial'),('Parallel + reset graph + 1.0-s first scan',after,'parallel'),('Parallel + reset graph + 0.6-s first scan',early,'parallel'),('Raw PCM diagnostic (unverified)',after,'off'),('Final deployed parallel: overlap fix',deployed,'parallel')]:
  for prompt in ('current','original'):
   group=[r for r in data if r['mode']==mode and r['prompt']==prompt]
   if not group:continue
   row={'condition':label,'prompt':prompt,'first_pcm_ms':median(r['first_pcm_ms'] for r in group),
        'full_ms':median(r['wall_ms'] for r in group),'audio_s':median(r['audio_s'] for r in group),
        'max_playback_gap_ms':max(r['gaps_ms'] for r in group),'end_verified':sum(bool(result(r).get('live_stream',{}).get('end_verified')) for r in group),'n':len(group)}
   rows.append(row)
 checks=json.loads((ROOT/'logs/streaming-boundaries/parallel-optimized-tests.json').read_text())
 report={'summary':rows,'before':before,'optimized':after,'earlier_scan':early,
         'browser_summary':[{'fixture':r['fixture'],'timing':r['timing'],'fixture_end_to_scheduled_audio_ms':r['end_to_scheduled_audio_ms']} for r in browser['rows']],
         'browser_passed':browser['passed'],'browser_receipt':browser_name,'cancellation':cancel,'real_injected_audio':checks,
         'deployed':deployed,'long_form':long_run,
         'codec_reset':read('codec-reset-graph.json'),'prefill_quality':read('prefill-quality.json')}
 (ROOT/'static/parallel-tts-verification.json').write_text(json.dumps(report,indent=2))
 table=''.join(f'<tr><td>{html.escape(r["condition"])}</td><td>{r["prompt"]}</td><td>{num(r["first_pcm_ms"])} ms</td><td>{num(r["full_ms"])} ms</td><td>{r["audio_s"]:.2f} s</td><td>{num(r["max_playback_gap_ms"])} ms</td><td>{r["end_verified"]}/{r["n"]}</td></tr>' for r in rows)
 brows=''.join('<tr><td>'+html.escape(r['fixture'])+'</td><td>'+html.escape(r['timing'].get('latency-tts','—'))+'</td><td>'+html.escape(r['timing'].get('latency-reply','—'))+'</td></tr>' for r in browser['rows'])
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Robby: parallel streamed-speech verification</title><style>
:root{color-scheme:light}body{font:17px/1.65 system-ui,sans-serif;margin:0;background:#f3f6fb;color:#172b40}main{max-width:1120px;margin:auto;padding:32px 22px}h1{font-size:2.1rem;line-height:1.2}h2{font-size:1.35rem}section{background:white;padding:22px;border-radius:16px;margin:20px 0;box-shadow:0 3px 18px #15365108}a{color:#0863a7}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px;border-bottom:1px solid #dfe6ed;text-align:left}th{background:#e8f0f8;white-space:nowrap}.note{border-left:4px solid #b07a26;padding:12px 18px;background:#fff8eb}code{overflow-wrap:anywhere;background:#eef2f5;padding:2px 5px}small{color:#536478}.flow{display:flex;flex-wrap:wrap;gap:12px}.flow div{background:#e8f2ed;padding:14px;border-radius:10px;flex:1;min-width:180px}li{margin:6px 0}</style><main>
<p><a href="/desk-robot/">← Robby demo</a> · <a href="/static/isolation-latency.html">Previous isolation study</a></p>
<h1>Faster streaming with parallel word verification</h1><p>13 November 2026 · Two RTX 3090 24-GB cards · Humaneness Voice Small 1.1 Alpha RL · Actual TTS and ASR outputs.</p>
<section><h2>Controlled results</h2><p>Identical authored prompts, Mira reference, temperature 0.8, CFG 2 and seeds 777–779. Median timings over three runs per condition. TTS starts per LLM sentence and streams incremental PCM within it. “First scan” means generated-audio duration, not time spent waiting in real time. The final deployment rows were measured after a restart; use the preceding same-process serial/parallel rows for the direct comparison.</p><div class="scroll"><table><thead><tr><th>Condition</th><th>Prompt</th><th>First PCM</th><th>Full request</th><th>Audio</th><th>Max simulated gap</th><th>Confirmed ending</th></tr></thead><tbody>TABLE</tbody></table></div><p class="note">Raw PCM is not word-verified and is not the live default. Historical 78–101-ms results used early release before strict opening-word confirmation. The old request still had alignment enabled and an approximately 10-s reference; it was not a full strict-ASR comparison.</p><p>The host also runs the podcast service. These are warm measurements under the recorded shared-host conditions, not guaranteed latency. Playback gaps simulate a listener starting immediately at first arrival; they exclude network jitter and physical devices.</p></section>
<section><h2>How the parallel gate works</h2><div class="flow"><div>GPU 0: TTS keeps generating<br>240 → 480 → 960 → 1,600 ms audio chunks</div><div>GPU 1: one ASR check at a time<br>Bounded overlapping windows, target-word order</div><div>Playback: confirmed PCM only<br>100-ms fade-in and final fade-out</div></div><p>The producer queues PCM instead of blocking on ASR. The verifier confirms the first two target words and then the ordered target prefix. It holds unsupported audio. After the final word it keeps 60 ms of margin and a 100-ms fade-out. Pending checks are coalesced; PCM is capped at 70 s, and individual ASR windows at 12 s. Cancellation discards late results.</p><p>Contractions, numbers and punctuation are normalized. One weak internal German verb ending can match only with two exact words on each side. Missing middle words or negations cannot be skipped, and final words must be recognized. ASR can still make mistakes; an unverified tail is withheld and marked incomplete rather than presented as fully verified.</p><p>The new path serves ordinary single-take streaming, used by Robby with quick replies off. Optional bridge batching, search and offline best-of-N retain their existing paths.</p></section>
<section><h2>GPU optimizations and quality tradeoffs</h2><p>The codec reset now replays its original operations as one CUDA graph: about <b>89 → 4.5 ms</b> warm. All eight reset comparisons produced bit-identical PCM. The initial graph captures are excluded from warm timings but retained in the data.</p><p>Eager semantic prefilling takes around 193–200 ms, despite only about 20 ms of GPU kernels. Profiling counted about 2,079 kernel launches. A padded CUDA-graph prototype reduced it to 17–35 ms but changed BF16 rounding and sampled speech. Nine authored clips per arm had mean Ultra WER 0% versus 2.02%, with two additional one-word deviations in the graphed arm. This small pilot is not a general quality study. <b>Padded prefill graphs remain off.</b></p><p>No model/reference shortening, speaker-threshold relaxation, faster playback or Torch/driver replacement was used. An initial isolated codec-loader experiment failed with OOM after using the wrong dtype option; the corrected BF16 test used bounded memory and passed. No live service was restarted by that failure.</p></section>
<section><h2>Public browser and failure checks</h2><p>Chrome through the existing HTTPS tunnel, with real CUDA VoxLock, authored synthetic microphone audio, ASR, speaker admission, API LLM, TTS and Web Audio scheduling. Final deployed two-turn latency-probe result: <b>BROWSER</b>.</p><div class="scroll"><table><thead><tr><th>Input fixture</th><th>TTS first PCM</th><th>Reply request → first PCM</th></tr></thead><tbody>BROWS</tbody></table></div><p>44 focused unit tests passed. Five real-ASR fixtures passed: clean target, unrelated leading/trailing speech, wrong-only speech, silence, and weak-ending recovery. The injected-audio probe simulates producer cadence; it is not a TTS throughput measurement. A live verified-stream disconnect released the model in CANCEL ms.</p><p class="note">A separate full two-person test registered both people and recognized a returning user, but admitted an unrelated background TV voice as Selma. That background-rejection test failed and is retained. This task did not change microphone identity thresholds.</p><p>The long-form probe initially exposed a timestamp-only overlap bug that truncated verified output. The fix anchors each new ASR window to a previously confirmed word sequence; it does not skip unverified words. LONG_RESULT</p><p>These checks do not establish perfect room-echo handling, speaker identity, dialect coverage or perceived voice quality. In an earlier browser probe the introduction was fully transcribed before its audio fixture ended; file end was not a reliable speech-end anchor. No sub-second end-to-end claim is made from such deltas. Browser output means scheduled audio, not physically measured DAC/loudspeaker latency. LLM and network delays remain variable.</p></section>
<section><h2>Reproduce and restart</h2><p><a href="parallel-tts-verification.json">Download measured JSON</a>. In the workspace read <code>robo-integration/PARALLEL_TTS_VERIFICATION.md</code> and <code>VOICE_ASSISTANT_TEST_PROTOCOL.md</code>. Run <code>parallel_verification_benchmark.py --label my-run</code>; use <code>--modes parallel --first-scan 0.6</code> for the scheduling comparison.</p><p>The TTS launcher remains <code>humaneness-small/start_rtx3090_tts.sh</code>, loopback port 8792. Verify the existing PID and stop only the idle TTS worker before starting another. Keep Robby 8793, Photon ASR 8822, the podcast service 8816 and the existing Cloudflare tunnel. Wait for TTS readiness after its several-minute warmup. API <code>speech_verification: "serial"</code> restores the previous verification scheduling for comparison. Current flags: <code>HVS_CODEC_RESET_GRAPH=1</code>, <code>HVS_PREFILL_GRAPH=0</code>.</p></section><small>Only authored synthetic audio is used in these reports. No private microphone recordings, voiceprints or API keys are published.</small></main></html>'''
 page=page.replace('TABLE',table).replace('BROWSER','passed' if browser['passed'] else 'FAILED — see receipt').replace('BROWS',brows).replace('CANCEL',num(cancel.get('disconnect_to_idle_ms',0)))
 r=long_run[0];boundary=result(r)['live_stream']
 long_text=(f"The final live 45-word regression {'passed' if r['passed'] and r['complete_target_verified'] else 'FAILED'}: "
            f"{boundary.get('ordered_target_words', '?')} target words confirmed, {r['audio_s']:.1f} s audio, "
            f"{num(r['first_pcm_ms'])} ms first verified PCM, {num(r['wall_ms'])} ms full request, "
            f"{num(r['gaps_ms'])} ms simulated playback gaps. This is one authored long-form case, not a broad accuracy evaluation.")
 page=page.replace('LONG_RESULT',long_text)
 (ROOT/'static/parallel-tts-verification.html').write_text(page)
 print(json.dumps(rows,indent=2))
if __name__=='__main__':main()
